monolith 2
# rotated.map -- the test package of turned boxes (box / block lines with `rot`): a walkable
# 30 degree ramp, a 45 degree yawed wall, a tumbled crate, a turned repeat row, turned blocks and a
# turned box in an `instanced on` material. Used by tests/unit/collision_test.sh and the engine
# verification of turned boxes (docs/live-editing.md 11.12). Brief: MAP.md.

# --- Materials (boxes use "default" until a `use` line picks another)
material "default" albedo 180 180 180 roughness 0.9 metalness 0
material "ramp" albedo 196 150 96 roughness 0.8
material "wall" albedo 120 140 170 roughness 0.85
material "crate" albedo 150 110 70 roughness 0.7
material "post" albedo 90 150 110 roughness 0.8
material "inst" albedo 200 80 70 roughness 0.6 instanced on

# --- Environment: the built-in defaults, every key written out
# Sky (sky.sunDirection follows sun.direction unless it is set)
env sky.mode procedural
env sky.size 1024
env sky.skyTopColor 120 132 145
env sky.skyHorizonColor 200 196 186
env sky.skyHorizonCurve 0.15
env sky.skyEnergy 1
env sky.groundBottomColor 48 46 44
env sky.groundHorizonColor 190 186 178
env sky.groundHorizonCurve 0.02
env sky.groundEnergy 1
env sky.sunColor 255 236 205
env sky.sunSizeDeg 2.5
env sky.sunCurve 0.15
env sky.sunEnergy 2
# Ambient light (IBL): a copy of the sky with these keys changed
env ambientSky.mode procedural
env ambientSky.size 256
env ambientSky.groundBottomColor 120 116 108
env ambientSky.groundHorizonCurve 0.1
# Sun: the shadowed directional light (static shadow tiles)
env sun.enabled on
env sun.direction 0.55 -0.78 0.3
env sun.color 255 238 214
env sun.energy 2
env sun.specular 1
env sun.fogEnergy 4
env sun.range 100
env sun.shadow on
env sun.softness 2
env sun.depthBias 0.0001
env sun.slopeBias 0.0015
env shadow.size 8192
# R3D environment
env background.color 130 130 130
env background.energy 1
env background.skyBlur 0
env background.rotation 0 0 0 1
env ambient.color 0 0 0
env ambient.energy 0.9
env ssao.enabled on
env ssao.sampleCount 16
env ssao.intensity 1.2
env ssao.power 1
env ssao.radius 1.2
env ssao.bias 0.03
env ssil.enabled on
env ssil.sampleCount 16
env ssil.giIntensity 1.2
env ssil.aoIntensity 1
env ssil.aoPower 1
env ssil.radius 5
env ssil.bias 0.03
env ssgi.enabled off
env ssgi.sliceCount 4
env ssgi.edgeFade 0.1
env ssgi.distanceFalloff 1
env ssgi.normalRejection 0
env ssgi.intensity 1
env ssgi.denoiseSteps 4
env ssr.enabled off
env ssr.maxIterations 64
env ssr.thickness 0.5
env ssr.edgeFade 0.25
env fog.mode exp2
env fog.color 150 148 143
env fog.start 1
env fog.end 50
env fog.density 0.0085
env fog.skyAffect 0.7
env volumetricFog.enabled on
env volumetricFog.scatteringDensity 0.012
env volumetricFog.absortionDensity 0.001
env volumetricFog.scatteringColor 255 244 228
env volumetricFog.anisotropy 0.4
env volumetricFog.emissionColor 150 148 143
env volumetricFog.emissionEnergy 0.12
env volumetricFog.skyAffect 0.5
env volumetricFog.length 90
env volumetricFog.stepSize 0.75
env dof.mode disabled
env dof.focusPoint 10
env dof.focusScale 1
env dof.nearScale 1
env dof.maxBlurSize 20
env bloom.mode mix
env bloom.levels 0.5
env bloom.intensity 0.04
env bloom.threshold 0
env bloom.softThreshold 0.5
env bloom.filterRadius 1
env autoExposure.enabled off
env autoExposure.minEV -1
env autoExposure.maxEV 1
env autoExposure.exposureCompensation 0
env autoExposure.adaptationToBright 0.5
env autoExposure.adaptationToDark 1
env tonemap.mode agx
env tonemap.exposure 0.9
env tonemap.white 1
env color.brightness 1
env color.contrast 1.05
env color.saturation 0.8
# Quality presets: exposure factor when a preset turns bloom off (keeps the mean brightness)
env bloom.offExposure 1.19

# --- Player start (feet, yaw) and spectator viewpoints (eye, target)
spawn 2 0 -5 90
viewpoint "Ramp" -2 3 2 10 2 -5
viewpoint "Overview" 22 16 14 2 0 -8
viewpoint "Wall and row" -17 4 3 -5 0.5 -11

# --- Geometry
group "ground"
box -100 -1 -100 100 0 100

# A 30 degree ramp climbing +X (a block rolled about +Z): its top starts at the ground at x 5.57
# and reaches y 5 at x 14.23, onto the platform
group "ramp"
use "ramp"
block 10 2.1268 -5 10 0.4 3 rot 0 0 30
box 14.3 0 -7 20 5 -3

# A wall yawed 45 degrees: 6 m long, 3 m tall, 0.4 m thick
group "yawed wall"
use "wall"
block 0 0 -15 6 3 0.4 rot 45 0 0

# A tumbled crate (a box line turned about all three axes) and a turned repeat row of posts
group "props"
use "crate"
box -7 0 -9 -6 1 -8 rot 25 35 15
use "post"
repeat 5 2 0 0 block -14 0 -4 1 2 0.3 rot 30 0 0

# An instanced material: one axis-aligned and one turned box
group "instanced"
use "inst"
box 4 0 -12 5 1 -11
box 6 0 -12 7 1.5 -11 rot 0 20 10
use "default"
